      "story_id": "01-group-detail-page",
      "name": "Group detail page route and template",
      "purpose": "Add the missing GET /library/chains/group?id=<uuid> SSR page so group item links no longer 404.",
      "agent": {
        "model": "sonnet",
        "skills": [
