          "frontend/astro/dist/pages/library/group_detail.html",
          "tests/integration/webapp/test_group_detail_page.py"
        ],
        "modify": [
          "apps/webapp/src/webapp/api/pages/chains.py"
        ]
      },
      "state_assumption": "cumulative",
      "acceptance_criteria": [
        "GET /library/chains/group?id=<valid-group-uuid> returns HTTP 200 for the group owner",
