        "test_type": "integration",
        "fixtures": [
          "make_user",
          "make_signal_chain"
        ],
        "assertions": [
          {
            "type": "http_status",
            "details": {
              "method": "GET",
              "route": "/library/chains/group?id={group.id}",
              "auth": "test_user",
